// Captures what real React 19.2.8 does with the two versions of the Technologies section, in real
// Chromium, and writes data/capture.json plus ../capture-data.js (the same data for the page).
//   cd react-data-loading/data && node capture.js
// Production build without StrictMode (what users get after npm run build), and the development
// build inside <StrictMode> (what npm run dev gives us). The server answers /Technologies.json
// after 300 ms. Only our own log lines and request counts are recorded: no paths, no headers.
const fs = require("fs"), path = require("path");
const H = require("../verify/harness"), P = require("../verify/programs");
(async () => {
  const browser = await H.openBrowser(), out = { react: H.VERSION, chromium: browser.version(), delayMs: 300, runs: {} };
  for (const [build, strict] of [["production", false], ["development", true]]) {
    const bundle = H.buildBundle(build);
    for (const name of ["suspense", "effect", "uncached", "typo"]) {
      const { page, counts, errors } = await H.openLab(browser, bundle, P.program(name, strict), name === "uncached" ? 100 : 300);
      await page.waitForTimeout(name === "uncached" ? 2000 : 1500);
      const log = await page.evaluate(() => LOG);
      if (name === "typo") out.runs["typo" + (strict ? "-strict" : "")] = { build, strict, errors: errors.map(e => e.replace(/http:\/\/lab\.test/g, "")), log, logLength: log.length };
      else out.runs[name + (strict ? "-strict" : "")] = { build, strict, requests: counts.json, log: name === "uncached" ? log.slice(0, 12) : log, logLength: log.length };
      await page.close();
    }
  }
  await browser.close();
  fs.writeFileSync(path.join(__dirname, "capture.json"), JSON.stringify(out, null, 1) + "\n");
  fs.writeFileSync(path.join(__dirname, "..", "capture-data.js"), "// Generated by data/capture.js from real React " + H.VERSION + " in Chromium. Do not edit.\nwindow.RDL_CAPTURE = " + JSON.stringify(out) + ";\n");
  console.log("wrote capture.json and ../capture-data.js:", Object.entries(out.runs).map(([k, v]) => k + " " + v.requests + " req").join(", "));
})();
